(()=>{const go=route=>{if(document.body.classList.contains('menu-open'))document.querySelector('.menu-control')?.click();if(parent!==window)parent.postMessage({type:'fieldbook:navigate',route},location.origin);else location.href='/#'+route;};
const expeditionLink=document.createElement('a');expeditionLink.className='header-expedition';expeditionLink.href='/#simulator/opportunity';expeditionLink.setAttribute('aria-label','Rover expedition');expeditionLink.innerHTML='<span class="long-label">Rover expedition</span><span class="short-label">Expedition</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';expeditionLink.onclick=e=>{e.preventDefault();go('simulator/opportunity');};document.querySelector('.header-actions')?.prepend(expeditionLink);
const section=document.createElement('section');section.className='fieldbook-continuation';section.innerHTML='<span class="eyebrow">THE NEXT CHAPTER</span><h2>The stories continue.<br>Now take the controls.</h2><p>Read the mission catalogue, inspect official NASA hardware, or join a guided rover expedition. Your place in this opening story is kept when you return.</p><div><button data-next="missions">Continue to the catalogue →</button><button data-next="simulator/opportunity">Begin rover expedition →</button></div>';document.querySelector('footer').before(section);section.querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.next));
const menu=document.querySelector('#menu');if(menu){for(const [route,label] of [['simulator/opportunity','Rover expedition ↗'],['missions','Continue the fieldbook →']]){const a=document.createElement('a');a.href='/#'+route;a.textContent=label;if(route.startsWith('simulator'))a.className='expedition-menu-link';a.onclick=e=>{e.preventDefault();go(route);};menu.append(a);}}
document.querySelectorAll('a[href="#archive"]').forEach(a=>{a.onclick=e=>{e.preventDefault();go('archive');};});
const motto=document.querySelector('.footer-bottom>span:first-child');if(motto){const words=document.createElement('span');words.className='motto-words';words.textContent=motto.textContent;motto.classList.add('orbit-motto');motto.replaceChildren(words);const satellite=document.createElement('span');satellite.className='motto-satellite';satellite.setAttribute('aria-hidden','true');satellite.innerHTML='<img src="/explore/assets/archive/hete-motto.png" alt="">';motto.append(satellite);}
let autoPaused=false,savedScroll=0;addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='fieldbook:visibility')return;const paused=!!window.explorerMotion?.paused;if(!e.data.visible)savedScroll=scrollY;if(!e.data.visible&&!paused){document.querySelector('.motion-control')?.click();autoPaused=true;}if(e.data.visible&&autoPaused){document.querySelector('.motion-control')?.click();autoPaused=false;requestAnimationFrame(()=>requestAnimationFrame(()=>scrollTo({top:savedScroll,behavior:'instant'})));}});})();
